 if(part.startsWith('window-switch:')){const index=Number(part.slice(14));if(floorTwo.windowSolved)return;if(floorTwo.windowPreview)return document.querySelector('#prompt').textContent='THE PATTERN IS STILL DISPLAYING · WATCH THE WINDOWS';if(index===floorTwo.windowCreatureIndex){floorTwo.windowProgress=0;saveFloorTwo();return resetFloorTwoEncounter('THE WINDOW CREATURE WAS BEHIND THAT SWITCH',()=>{})}const sequence=floorTwo.windowRounds[floorTwo.windowRound];if(index!==sequence[floorTwo.windowProgress]){floorTwo.windowProgress=0;saveFloorTwo();document.querySelector('#prompt').textContent='WRONG WINDOW · THE PATTERN RESTARTS';return buildFloorTwoWindowPuzzle()}floorTwo.windowProgress++;pickupTone();if(floorTwo.windowProgress<sequence.length){saveFloorTwo();return document.querySelector('#prompt').textContent=`CORRECT · ${floorTwo.windowProgress} / ${sequence.length}`}floorTwo.windowRound++;floorTwo.windowProgress=0;if(floorTwo.windowRound>=3){floorTwo.windowSolved=true;saveFloorTwo();playPurgeCrash();objective.textContent='All three patterns are complete. Continue along the façade.';return buildFloorTwoWindowPuzzle()}saveFloorTwo();document.querySelector('#prompt').textContent=`ROUND ${floorTwo.windowRound} COMPLETE · NEXT PATTERN`;return buildFloorTwoWindowPuzzle()}
