function floorTwoDeathMonster(reason){const phases={6:['ballroom-guest','Masked Guest'],7:['watcher','The Watcher'],10:['gardener','The Gardener'],11:['window-creature','Window Creature'],12:['false-guest','False Guest']};return phases[floorTwo?.phase]&&(/GUEST|WATCHER|GARDENER|WINDOW CREATURE/.test(reason)||floorTwo.phase!==6)?phases[floorTwo.phase]:null}
